public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) return "cannot be travelled";
    int dim = start.length;
    if (dim == 0) return "cannot be travelled";
    // Helper to build key for coordinate array
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    // Quick check if start equals end
    if (java.util.Arrays.equals(start, end)) return "can be travelled";
    // Build adjacency map
    java.util.Map<String, java.util.List<int[]>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != dim * 2) continue;
            int[] src = new int[dim];
            int[] dst = new int[dim];
            System.arraycopy(path, 0, src, 0, dim);
            System.arraycopy(path, dim, dst, 0, dim);
            String srcKey = coordKey.apply(src);
            String dstKey = coordKey.apply(dst);
            adj.computeIfAbsent(srcKey, k -> new java.util.ArrayList<>()).add(dst);
            adj.computeIfAbsent(dstKey, k -> new java.util.ArrayList<>()).add(src); // undirected
        }
    }
    // BFS to search for end
    java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(start);
    visited.add(coordKey.apply(start));
    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        String curKey = coordKey.apply(cur);
        java.util.List<int[]> neighbors = adj.get(curKey);
        if (neighbors == null) continue;
        for (int[] neigh : neighbors) {
            String neighKey = coordKey.apply(neigh);
            if (visited.contains(neighKey)) continue;
            if (java.util.Arrays.equals(neigh, end)) {
                return "can be travelled";
            }
            visited.add(neighKey);
            queue.add(neigh);
        }
    }
    return "cannot be travelled";
}

